use kni_core::duplicate_point_audit::{audit_duplicate_points,AuditError};
use kni_core::reference_slice::{DrawnGlyph,Point,ReferenceRing,Span};
fn p(x:f64,y:f64)->Point{Point{x,y}}
#[test]fn classifies_all_pairs_roles_adjacency_cross_contour_and_closure(){let g=DrawnGlyph{glyph_id:"synthetic".into(),rings:vec![ReferenceRing{start:p(0.,0.),spans:vec![Span::Cubic{control_one:p(0.,0.),control_two:p(0.,0.),end:p(1.,0.)},Span::Line{end:p(0.,0.)}]},ReferenceRing{start:p(-0.,0.),spans:vec![Span::Line{end:p(2.,0.)},Span::Line{end:p(0.,0.)}]}]};let before=format!("{g:?}");let r=audit_duplicate_points(&g).unwrap();assert_eq!(r.point_count,8);assert_eq!(r.pair_count,15);assert_eq!(r.consecutive,2);assert_eq!(r.non_adjacent,13);assert_eq!(r.same_contour,7);assert_eq!(r.different_contour,8);assert_eq!(r.on_on,6);assert_eq!(r.on_off,8);assert_eq!(r.off_off,1);assert_eq!(r.explicit_closure_pairs,2);assert_eq!(r.nonclosure_pairs,13);assert_eq!(before,format!("{g:?}"));assert!(r.row(&g.glyph_id).contains("not_proven_redundancy"));}
#[test]fn nonfinite_rejected_not_grouped(){let g=DrawnGlyph{glyph_id:"nonfinite".into(),rings:vec![ReferenceRing{start:p(f64::NAN,0.),spans:vec![]}]};assert!(matches!(audit_duplicate_points(&g),Err(AuditError::NonFiniteCoordinate{contour:0,position:0})));}
